Section RED.
  Variable L : heap_layout.
  Variable HI : heap_iface usegs L.
  Hypothesis HFREE : hl_free L = U_FREE.
  Hypothesis HCALLOC : hl_calloc L = U_CALLOC.
  Hypothesis HLS : 0 <= hl_stack L.
  Hypothesis SW : forall a, hl_static L a -> hl_written L a.
  Hypothesis DIMG : hl_img_lo L <= hl_data_lo L /\ hl_data_hi L <= hl_img_hi L.
  Hypothesis HND : forall h LB m mo, HEAP usegs L HI h LB m mo -> List.NoDup (map fst LB).
  Hypothesis CRP : const_at L RP 8.
  Lemma RPB_of : forall m, statics_ok usegs L m -> const_at L RP 8 -> bytes_at usegs m RP (u32s RPW).
  Proof.
    intros m SO CA. pose proof (statics_ok_cells usegs L m RP (u32s RPW) SO CA ltac:(vm_compute; reflexivity)) as [_ HB].
    cbn [cells_bytes cbytes] in HB. rewrite app_nil_r in HB. exact HB.
  Qed.

